import { env } from "cloudflare:workers";
import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import {
  SyncedStateServer,
  syncedStateRoutes,
} from "rwsdk/use-synced-state/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { AuctionPage } from "@/app/pages/auction/AuctionPage";
import { AuctionRoom } from "@/durableObjects/auctionRoom";

// Durable Objects must be exported from the worker entry module so Cloudflare
// (and wrangler's local emulation) can find them.
export { SyncedStateServer, AuctionRoom };

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  // Wires up the realtime (`useSyncedState`) transport routes.
  ...syncedStateRoutes(() => env.SYNCED_STATE_SERVER),
  render(Document, [
    route("/", Home),
    route("/auction/:itemId", AuctionPage),
  ]),
]);

"use server";

import { env } from "cloudflare:workers";
import { serverQuery } from "rwsdk/worker";
import type { AuctionSnapshot } from "@/durableObjects/auctionRoom";

function getAuctionRoomStub(itemId: string) {
  const id = env.AUCTION_ROOM.idFromName(itemId);
  return env.AUCTION_ROOM.get(id);
}

// Data-only server query: fetches (and lazily initializes) the current
// auction snapshot for an item. Does not rehydrate/re-render the page.
export const getAuctionSnapshot = serverQuery(
  async (itemId: string): Promise<AuctionSnapshot> => {
    const stub = getAuctionRoomStub(itemId);
    return stub.getSnapshot(itemId);
  },
);

// Data-only server query used to submit a bid. All validation happens on the
// server (inside the Durable Object) — the client cannot bypass it.
export const placeBid = serverQuery(
  async (
    itemId: string,
    bidderName: string,
    amount: number,
  ): Promise<{ ok: boolean; error?: string; snapshot: AuctionSnapshot }> => {
    const stub = getAuctionRoomStub(itemId);
    return stub.placeBid(itemId, bidderName, amount);
  },
);

import type { RequestInfo } from "rwsdk/worker";

import { AuctionClient } from "./AuctionClient";
import { getAuctionSnapshot } from "./functions";

export async function AuctionPage({ params, request }: RequestInfo) {
  const itemId = params.itemId as string;
  const url = new URL(request.url);
  const myName = url.searchParams.get("name")?.trim() || "Anonymous";

  const snapshot = await getAuctionSnapshot(itemId);

  return (
    <AuctionClient itemId={itemId} myName={myName} initialSnapshot={snapshot} />
  );
}

